 data jsonb := $items$[{"id":"M07-A26-01","uuid":"e17513e7-3af0-5f25-8fc8-6a9e6dbc33c7","lesson":1,"format":"Y1","stem":"Scratch sprayti dastlab (−70; 40) nuqtada. Quyidagi bloklar bajarilgach, uning yakuniy koordinatasini aniqlang.\n\n```text\nrepeat (3)\n  change x by (25)\n  change y by (-15)\nend\n```","options":["(5; −5)","(−45; 25)","(5; 85)","(−145; −5)"],"correct":0,"explanation":"Har takrorlashda x +25, y −15. 3 marta: x=−70+3×25=5, y=40−3×15=−5.","difficulty":3,"cognitive":"qollash","source":"ICT 5/6 (2020/2021) Scratch/LOGO mavzulari; 2026 spetsifikatsiya PDF 4","assets":[],"status":"review","lesson_id":"97000000-0000-4000-8000-000000000001","construct_id":"55eb8372-7378-437a-99ed-ffc77bd5fc4c","source_reference":"M07-AUDIT-20261020:M07-A26-01; source=ICT 5/6 (2020/2021) Scratch/LOGO mavzulari; 2026 spetsifikatsiya PDF 4; ORIGINAL_REVIEW","payload":{"correct_option_id":"faa39153-27dc-5069-8699-39a7b6d24a08"},"option_rows":[{"id":"faa39153-27dc-5069-8699-39a7b6d24a08","side":"a","order_idx":0,"content":"(5; −5)"},{"id":"d88fb9e2-a6f1-5921-aa7c-e2bf9c94a17e","side":"a","order_idx":1,"content":"(−45; 25)"},{"id":"18f7688d-ba41-52a5-8aaa-28a225ae1635","side":"a","order_idx":2,"content":"(5; 85)"},{"id":"561ba4dc-8451-54bd-8c71-4a1dc4590890","side":"a","order_idx":3,"content":"(−145; −5)"}]},{"id":"M07-A26-02","uuid":"4874ad9f-8ed3-5190-9c7a-ba8a9d8d223b","lesson":2,"format":"Y1","stem":"Scratchdagi `s` o‘zgaruvchisi quyidagi skriptni bajargach qanday qiymatga ega bo‘ladi?\n\n```text\nset [s] to (2)\nrepeat (4)\n  change [s] by (3)\nend\nif <(s) > (10)> then\n  change [s] by (-5)\nend\n```","options":["14","9","7","5"],"correct":1,"explanation":"Dastlab s=2. 4 ta qo‘shishdan keyin s=14. 14>10 rost, shuning uchun 14−5=9.","difficulty":3,"cognitive":"qollash","source":"ICT 5/6 (2020/2021) Scratch/LOGO mavzulari; 2026 spetsifikatsiya PDF 4","assets":[],"status":"review","lesson_id":"ea3cf78e-e740-d82d-5c05-bf9c1a1dd5b1","construct_id":"55eb8372-7378-437a-99ed-ffc